    h, w = len(grid), len(grid[0])
    # The repeated 3x3 stencil is the complement of the input's occupied mask.
    stencil = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value != 0:
                for dr, dc in stencil:
                    out[3 * r + dr][3 * c + dc] = value
    return out
